opendesk.sidebar-tools.installed.v1.css:
:root{font-family:system-ui,-apple-system,"PingFang SC",sans-serif;color:#25364e;background:#fff}
*{box-sizing:border-box}body{margin:0}.notes-app{padding:14px;max-width:760px;margin:auto}
.notes-heading{display:flex;align-items:flex-start;gap:12px;padding:10px 0 13px;border-bottom:1px solid #e7edf7}
.notes-heading img{height:16px;width:16px;margin-top:7px}.notes-heading h1{font-size:19px;line-height:1.3;margin:0}
.notes-heading p{font-size:12px;line-height:1.5;color:#60728d;margin:6px 0 0;overflow-wrap:anywhere}
label{display:block;font-size:12px;font-weight:650;margin:17px 0 7px}
textarea,input{font:inherit;font-size:13px;width:100%;border:1px solid #cbd6e6;border-radius:9px;padding:10px}
textarea{resize:vertical;min-height:120px}
button{border:1px solid #bdcff2;background:#edf3ff;color:#2f56af;border-radius:9px;font-size:12px;font-weight:650;padding:9px 11px;cursor:pointer}
button:first-child{background:#315bd1;color:#fff}
.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}#note-status{font-size:12px;color:#526585;line-height:1.5}
details{border-top:1px solid #e7edf7;margin-top:14px;padding-top:10px;font-size:12px}summary{cursor:pointer;font-weight:650}
details button{margin-top:9px}:focus-visible{outline:2px solid #315bd1;outline-offset:2px}

opendesk.sidebar-tools.installed.v1.js:
(() => {
  'use strict';
  const {root,request}=globalThis.OpenDeskTool;
  const el=id=>root.querySelector('#'+id);
  const show=message=>{el('note-status').textContent=message;};
  async function refreshPage() {
    try {
      const page=await request('currentPage.info');
      el('page-summary').textContent=page.status==='available'?
        page.title+' · '+page.url:'当前网页不可用：'+page.message;
    }catch(error){el('page-summary').textContent=error.message;}
  }
  async function restore() {
    try{const result=await request('storage.get',{key:'note'});el('note-text').value=String(result.value||'');}
    catch(error){show('恢复笔记失败：'+error.message);}
  }
  el('refresh-page').addEventListener('click',()=>void refreshPage());
  el('save-note').addEventListener('click',async()=>{
    try{await request('storage.set',{key:'note',value:el('note-text').value});show('笔记已保存到此工具的本地存储');}
    catch(error){show('保存失败：'+error.message);}
  });
  el('open-task').addEventListener('click',async()=>{
    try{await request('tasks.open',{taskId:el('task-name').value.trim()});}
    catch(error){show('打开任务失败：'+error.message);}
  });
  void Promise.all([refreshPage(),restore()]);
})();
